mapper.select:
SELECT e.* FROM equipment e JOIN lab l ON l.id=e.lab_id AND l.deleted=0
WHERE e.deleted=0
AND l.admin_id=#{managerId}
AND e.lab_id=#{query.labId}
AND e.status=#{query.status}
AND e.name LIKE CONCAT('%',#{query.name},'%')
AND e.model LIKE CONCAT('%',#{query.model},'%')
AND e.equipment_code LIKE CONCAT('%',#{query.equipmentCode},'%')
ORDER BY e.id DESC LIMIT 2001
